// GENERATED by `python -m contracts.export_ts` from contracts/models.py. DO NOT EDIT BY HAND.
// Units: kWh/yr, GBP, kgCO2e, m2, W/m2K, W/K. Savings = baseline - after (negative = increase).
// Every uncertain number is a Distribution (mean, median, mode, std, percentiles, intervals, tails).

export const SCHEMA_VERSION = "0.4.0";

/** Posterior percentiles; must be non-decreasing from p1 to p99. */
export interface Percentiles {
  p1: number;
  p5: number;
  p10: number;
  p25: number;
  p50: number;
  p75: number;
  p90: number;
  p95: number;
  p99: number;
}

/** Central (equal-tailed) credible interval, e.g. level 0.9 = P5..P95. */
export interface CredibleInterval {
  level: number;
  lo: number;
  hi: number;
}

/** Probability that the quantity falls beyond a meaningful threshold, e.g. P(saving < 0). */
export interface TailProbability {
  /** Human-readable event, e.g. 'bill rises by more than £100/yr' */
  label: string;
  threshold: number;
  direction: "below" | "above";
  probability: number;
}

/** Sample histogram for the UI density plot; len(bin_edges) == len(counts) + 1. */
export interface Histogram {
  bin_edges: number[];
  counts: number[];
}

/** Full posterior summary of an uncertain quantity (replaces the old mean/lo/hi Interval). Built from posterior samples by ``contracts.summarise.summarise``. A known-exact value (e.g. gas after a heat pump removes the boiler) is a degenerate distribution: std = 0. */
export interface Distribution {
  /** e.g. 'kWh/yr', 'GBP/yr', 'kgCO2e/yr', 'points', '%' */
  unit: string;
  /** Posterior samples the summary was computed from */
  n_samples: number;
  mean: number;
  /** Equals percentiles.p50 */
  median: number;
  /** Most likely value: peak of the sample density (KDE) */
  mode: number;
  std: number;
  /** Sample skewness; |skew| > 0.5 -> headline uses the median */
  skewness?: number;
  percentiles: Percentiles;
  /** At least the 50% and 90% intervals */
  credible_intervals: CredibleInterval[];
  tail_probabilities?: TailProbability[];
  /** Which side is the bad outcome (low for savings, high for costs) */
  worst_tail?: "low" | "high";
  /** Mean of the worst 5% of samples (expected shortfall) */
  worst_5pct_mean: number;
  histogram?: Histogram | null;
  /** Which centre the UI/LLM shows first */
  headline?: "mean" | "median";
}

/** Where a number came from. Every result carries one. */
export interface Provenance {
  engine: "physics_l1" | "bayes_calibration" | "surrogate_deeponet" | "sap_estimator" | "ebm" | "xgboost" | "gnn" | "bayesian_hedonic" | "hedonic" | "dr_learner" | "rules" | "jev" | "claude" | "haiku_vision" | "template" | "mock";
  model_version: string;
  data_version: string;
  seed?: number | null;
  /** Posterior samples used */
  n_samples?: number | null;
}

/** One additive term of a glass-box model (EBM shape function or hedonic coefficient x value). */
export interface FeatureContribution {
  feature: string;
  /** The input value for this home */
  value?: number | string | null;
  /** Additive contribution in the model's output unit */
  contribution: number;
  unit: string;
}

