  roof_u: number;
  floor_u: number;
  window_u: number;
  door_u?: number;
  /** W/m2K added over exposed area */
  thermal_bridging_y?: number;
  air_changes_per_hour: number;
  volume_m3: number;
  /** Calibrated: scales total fabric + ventilation loss */
  heat_loss_multiplier?: number;
  setpoint_c?: number;
  heating_hours_per_day?: number;
  /** Boiler seasonal efficiency or heat-pump SCOP */
