/** One step of the improvement ladder: the marginal effect of adding this retrofit after the earlier steps. */
export interface RetrofitEffect {
  retrofit_id: string;
  /** Position in the recommended sequence */
  order: number;
  feasibility: Feasibility;
  /** Marginal, in sequence; negative = increase */
  electricity_saving_kwh: Distribution;
  gas_saving_kwh: Distribution;
  carbon_saving_kgco2e: Distribution;
  bill_saving_gbp: Distribution;
  cost_gbp?: Distribution | null;
  /** Set when the catalogue cost is unsourced */
  cost_unavailable_reason?: string | null;
  /** Marginal grid import + gas saving */
  purchased_energy_saving_kwh?: Distribution | null;
  /** Projected score after this step (cumulative) */
  score_after?: Distribution | null;
  /** Improvement potential reached after steps 1..order */
  improvement_potential_cumulative_pct?: Distribution | null;
  payback_years?: Distribution | null;
  /** Under ScenarioSpec.goal, cost uncertainty included */
  p_net_benefit: number;
  /** p_feasible * p_net_benefit */
  p_suitable: number;
  suitability: "High" | "Medium" | "Low";
  /** P(step adds >= the documented gain threshold) */
  p_gain_above_threshold?: number | null;
  verdict?: "recommended" | "optional" | "not_worth_adding" | "needs_survey" | "not_feasible" | null;
  /** Short human-readable reason built from rule codes/KB, not LLM */
  reason: string;
}

/** PS section 3: 100 x (E_base - E_after) / E_base on purchased energy, with ALL feasible retrofits run together. */
