/** PS section 3: why a home performs poorly, with the evidence behind it. */
export interface KeyIssue {
  code: "high_intensity" | "poor_insulation" | "old_heating" | "single_glazing" | "no_renewables" | "no_controls" | "data_conflict" | "missing_data";
  /** e.g. 'High energy use per m2 for a home like this' */
  label: string;
  severity: "high" | "medium" | "low";
  /** e.g. {'kwh_m2': 231, 'peer_p50': 165} */
  evidence?: Record<string, number | string>;
  /** e.g. P(intensity above peers) */
  probability?: number | null;
}

export interface ScoreResult {
  /** Rounded weighted sum (of the posterior mean inputs) */
  score: number;
  /** Score over posterior samples */
  score_distribution?: Distribution | null;
  /** Mode of band_probabilities (most probable band) */
  band: "Highly efficient" | "Good" | "Moderate" | "Poor" | "Very poor";
  /** P(each band); sums to 1 */
  band_probabilities?: Record<string, number>;
  p_poor_or_very_poor?: number | null;
  components: ScoreComponent[];
  key_issues?: KeyIssue[];
  /** True for a post-retrofit score (uses RatingEstimate) */
  projected?: boolean;
  rating_source?: "recorded_epc" | "estimated" | "missing";
  /** e.g. local-authority band shares from EPC live table D1 */
  peer_context?: Record<string, number | string>;
  /** Version of contracts/score_mapping.json used */
  mapping_version?: string;
}

export interface ValueImpact {
  /** Baseline valuation (never a historical sale price) */
  current_value_gbp: number | null;
  /** Set when the current value is model-estimated rather than provided */
  current_value_distribution?: Distribution | null;
  /** Recorded EPC band */
  band_before?: string | null;
  /** From RatingEstimate (sap_estimator), not a lodged EPC */
  band_after?: string | null;
  uplift_pct?: Distribution | null;
  value_after_gbp?: Distribution | null;
  /** Posterior of beta for this region x type */
  rating_effect_pct_per_sap_point?: Distribution | null;
  /** Why the home is worth what it is */
  price_drivers?: FeatureContribution[];
  method: "bayesian_hedonic" | "hedonic_quantile" | "dr_learner" | "green_twin_matching" | "unavailable";
  label?: "indicative";
  /** Must accompany every display of the value range */
  wording?: string;
  unavailable_reason?: string | null;
}

/** A matched greener comparable home, shown only as ranges (never an address). */
export interface GreenTwin {
  match_rank: number;
  /** Green Home Score points greener than this home */
  score_gap: number;
  price_per_m2_gbp: Distribution;
  energy_cost_gbp?: Distribution | null;
  epc_band?: string | null;
  /** Matched on, e.g. ['type', 'age band', 'LSOA'] */
  same?: string[];
}

export interface Feasibility {
  retrofit_id: string;
  status: "feasible" | "feasible_with_conditions" | "needs_survey" | "infeasible";
  decided_by: "rules" | "jev" | "llm_fallback" | "agent";
  reason_codes?: string[];
  /** Human-readable, from rules/KB (never the LLM) */
  reasons?: string[];
  /** 1.0/0.0 for rules; recalibrated confidence for Jev */
  p_feasible: number;
}

export interface FeasibilityReport {
  property_id: string;
  items: Feasibility[];
  rules_version: string;
  jev_used?: boolean;
  router?: "jev" | "llm_fallback" | "rules_only";
}

/** Output of the System-1 router (Jev or Claude fallback). */
export interface WhatIfRoute {
  intent: "numeric" | "comparative" | "feasibility" | "explain" | "out_of_scope";
  confidence: number;
  scenario?: ScenarioSpec | null;
  needs_clarification?: boolean;
  clarifying_question?: string | null;
  router: "jev" | "llm_fallback";
}

/** Validator output for one LLM answer. */
export interface ExplanationCheck {
  numbers_found: string[];
  unsupported_numbers: string[];
  jev_supported_probability?: number | null;
  passed: boolean;
}

export interface ChatTurn {
  role: "user" | "assistant";
  content: string;
}

export interface Citation {
  source: "tool_result" | "doc" | "rule" | "dataset";
  /** scenario_id, doc id, rule id or dataset id */
  ref: string;
  snippet?: string | null;
}

export interface ToolCallRecord {
  name: "get_home_facts" | "get_results" | "run_scenario" | "search_docs" | "query_graph" | "get_energy_prior" | "rank_recommendations" | "get_customer_memory" | "propose_memory";
  input: Record<string, unknown>;
  /** e.g. the scenario_id a run_scenario call produced */
  output_ref?: string | null;
}

export interface ChatRequest {
  property_id: string;
  customer_id?: string | null;
  message: string;
  history?: ChatTurn[];
}

export interface ChatResponse {
  answer: string;
  route?: WhatIfRoute | null;
  tool_calls?: ToolCallRecord[];
  citations?: Citation[];
  check: ExplanationCheck;
  scenario_result_id?: string | null;
  fallback?: "none" | "regenerated" | "template";
  /** LLM model id, or None for the template explainer */
  model?: string | null;
}

export interface CustomerMemory {
  customer_id: string;
  /** e.g. {'type':'constraint','value':'renting'} */
  facts?: Record<string, string>[];
  completed_retrofits?: RetrofitAction[];
  /** {'retrofit_id':..,'reason':..} */
  rejected?: Record<string, string>[];
  saved_scenarios?: string[];
}

export interface RetrofitItem {
  id: string;
  name: string;
  category: "fabric" | "glazing" | "heating" | "renewables" | "controls" | "airtightness" | "lighting" | "tariff";
  /** TwinParams edits: a number sets the field; a string 'x<k>' multiplies it (e.g. 'x0.25'); other strings set a categorical field (e.g. tariff) */
  twin_edits: Record<string, number | string>;
  /** Rule ids that veto this retrofit */
  blocked_by_rules?: string[];
  /** Should come after these (ordering) */
  depends_on?: string[];
  /** Mutually exclusive retrofits */
  excludes?: string[];
  cost_gbp_low?: number | null;
  cost_gbp_central?: number | null;
  cost_gbp_high?: number | null;
  /** per_home | per_m2 | per_kwp | per_window */
  cost_basis?: string;
  cost_price_year?: string | null;
  /** unsourced -> no cost figure is ever shown (cost = null + reason) */
  cost_status?: "sourced" | "secondary_source" | "unsourced";
  lifetime_years?: number | null;
  grants?: string[];
  /** Continuous sizing bounds, e.g. {'kwp_min':1,'kwp_max':6} */
  sizing?: Record<string, number> | null;
  /** False for tariff switches: bills change, energy does not */
  changes_kwh?: boolean;
  /** Citation for cost/impact assumptions */
  source: string;
}

export interface RetrofitAction {
  retrofit_id: string;
  /** e.g. kWp, mm, kW */
  size?: number | null;
  /** Roadmap year (0 = now) */
  stage_year?: number | null;
}

export interface ScenarioSpec {
  schema_version?: string;
  scenario_id: string;
  property_id: string;
  /** Empty = baseline only */
  retrofits?: RetrofitAction[];
  weather?: "typical" | "cold_year" | "warm_year" | "forecast_week" | "ukcp18_2050";
  /** Posterior samples to propagate */
  n_samples?: number;
  include_value?: boolean;
  include_pareto?: boolean;
  include_element_heat_loss?: boolean;
  include_electricity_profile?: boolean;
  seed?: number;
  /** Defines 'net benefit' for suitability/verdicts; never changes computed numbers */
  goal?: "bills" | "carbon";
  requested_by?: "ui" | "llm" | "batch" | "jev_router" | "eval";
}

export interface ScenarioResult {
  schema_version?: string;
  scenario_id: string;
  property_id: string;
  provenance: Provenance;
  goal?: "bills" | "carbon";
  calibration?: CalibrationResult | null;
  baseline: EnergyBreakdown;
  after: EnergyBreakdown;
  /** baseline - after; negative = increase */
  electricity_saving_kwh: Distribution;
  gas_saving_kwh: Distribution;
  purchased_energy_saving_kwh: Distribution;
  improvement_potential: ImprovementPotential;
  /** Null if a fuel has no sourced factor */
  carbon_saving_kgco2e?: Distribution | null;
  carbon_unavailable_reason?: string | null;
  /** kgCO2e/kWh from contracts/emission_factors.json, e.g. {'electricity':0.19553,'gas':0.18296} */
  emission_factors: Record<string, number>;
  emission_factor_source: string;
  bill_saving_gbp: Distribution;
  electricity_profile_after?: ElectricityProfileSummary | null;
  score_before: ScoreResult;
  /** Uses rating_after (estimated) for the energy-efficiency component */
  score_after: ScoreResult;
  rating_after?: RatingEstimate | null;
  feasibility?: FeasibilityReport | null;
  /** The improvement ladder, in order */
  retrofits?: RetrofitEffect[];
  value: ValueImpact;
  element_heat_loss_before?: ElementHeatLoss[];
  element_heat_loss_after?: ElementHeatLoss[];
  pareto?: ParetoPoint[];
  data_confidence?: "high" | "medium" | "low";
  /** Missing/conflicting data, OOD, assumptions */
  warnings?: string[];
}

/** One area on the Lloyds heat map (LSOA or local authority). Synthetic customer layers are labelled. */
export interface DashboardArea {
  area_code: string;
  area_type: "lsoa" | "local_authority" | "postcode_district";
  n_homes_modelled: number;
  /** Share with score >= 65 */
  share_green?: Distribution | null;
  share_poor?: Distribution | null;
  finance_demand_gbp?: Distribution | null;
  carbon_potential_t?: Distribution | null;
  gnn_expected_electricity_kwh?: Distribution | null;
  gnn_expected_gas_kwh?: Distribution | null;
  observed?: LSOAConsumption | null;
  /** Official EPC live-table figures (LA level) */
  epc_stats?: AreaEPCStats | null;
  off_gas_grid_share?: number | null;
  /** Synthetic customer base; always labelled */
  synthetic_customers?: number | null;
}

export type BuiltForm = "detached" | "semi_detached" | "mid_terrace" | "end_terrace" | "enclosed_mid_terrace" | "not_applicable";

export type Control = "none" | "programmer" | "room_thermostat" | "trvs" | "smart_thermostat" | "zoned_control" | "smart_meter";

export type FloorType = "suspended_timber" | "solid" | "another_dwelling_below";

export type GlazingType = "single" | "secondary" | "double_pre_2002" | "double_post_2002" | "triple";

export type HeatingSystem = "gas_boiler_condensing" | "gas_boiler_non_condensing" | "oil_boiler" | "lpg_boiler" | "electric_storage" | "electric_storage_hhr" | "electric_direct" | "air_source_heat_pump" | "ground_source_heat_pump" | "district_heating" | "communal_boiler" | "solid_fuel";

export type PropertyType = "house" | "bungalow" | "flat" | "maisonette";

export type RoofType = "pitched_loft" | "pitched_room_in_roof" | "flat" | "another_dwelling_above";

export type Tenure = "owner_occupied" | "private_rented" | "social_rented" | "unknown";

export type WallInsulation = "none" | "cavity_filled" | "internal" | "external" | "as_built";

export type WallType = "solid_brick" | "solid_stone" | "cavity" | "timber_frame" | "system_built";
